    resources = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    territory = observation.get('territory', [])
    game_type = observation.get('game_type', '')

    x, y = agent_pos

    # Helper function to check for obstacles or enemy presence
    def is_safe(nx, ny):
        # Check grid bounds
        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]):
            cell = grid[nx][ny]
            # Assuming 'wall' indicates obstacle, 'enemy' indicates opponent
            if cell == 'wall' or cell == 'enemy':
                return False
            return True
        return False

    # For resource collection or territory control, move towards nearest resource/territory
    if game_type in ('resource_collection', 'territory_control'):
        targets = resources if game_type == 'resource_collection' else territory
