                if target_pos[1] > y:
                    dy_candidate = 1
                elif target_pos[1] < y:
                    dy_candidate = -1
                # Check safety
                if is_safe(x + dx_candidate, y + dy_candidate):
                    dx, dy = dx_candidate, dy_candidate
                else:
                    # Try alternative directions
                    for alt_dx, alt_dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nx, ny = x + alt_dx, y + alt_dy
                        if is_safe(nx, ny):
                            dx, dy = alt_dx, alt_dy
                            break

    # For pursuit or evasion, move away from nearest opponent if exists
    elif game_type in ('pursuit', 'evade'):
        if opponents:
            # Find closest opponent
            min_dist = float('inf')
            opponent_pos = None
            for ox, oy in opponents:
                dist = abs(ox - x) + abs(oy - y)
                if dist < min_dist:
                    min_dist = dist
                    opponent_pos = (ox, oy)
            if opponent_pos:
                ox, oy = opponent_pos
                dx_candidate = 0
                dy_candidate = 0
                if ox > x:
                    dx_candidate = -1
                elif ox < x:
                    dx_candidate = 1
                if oy > y:
                    dy_candidate = -1
                elif oy < y:
                    dy_candidate = 1
                # Attempt to move away
                for dir_x in [0, dx_candidate]:
                    for dir_y in [0, dy_candidate]:
                        nx, ny = x + dir_x, y + dir_y
                        if is_safe(nx, ny):
                            dx, dy = dir_x, dir_y
                            break
                    else:
                        continue
                    break

    # Default: move randomly to a safe adjacent cell
    else:
        for dir_x, dir_y in [(-1,0), (1,0), (0,-1), (0,1), (0,0)]:
            nx, ny = x + dir_x, y + dir_y
            if is_safe(nx, ny):
                dx, dy = dir_x, dir_y
                break

    # Ensure dx and dy within allowed set
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]
